<script setup lang="ts">
import { computed, h, onMounted, reactive, ref } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { ElAlert, ElButton, ElForm, ElFormItem, ElInput, ElInputNumber, ElSwitch, ElSelect, ElOption, ElMessageBox, ElTableV2, ElAutoResizer } from 'element-plus'
import { getSession, type Model } from '@/api/client'
import { emptyRule, useReplaceRules } from './replaceRules'
const { items, busy, error, notice, savedId, load, save, remove } = useReplaceRules()
const draft = reactive(emptyRule()), selected = ref<string>(), baseline = ref(JSON.stringify(draft))
const dirty = computed(() => JSON.stringify(draft) !== baseline.value)
async function abandon() { if (!dirty.value) return true; try { await ElMessageBox.confirm('放弃尚未保存的规则修改？', '切换规则', { confirmButtonText: '放弃修改', cancelButtonText: '继续编辑', type: 'warning' }); return true } catch { return false } }
async function edit(rule?: Model<'ReplaceRule'>) { if (!await abandon()) return; Object.assign(draft, emptyRule(), rule ? { name: rule.name, group_name: rule.group_name || '默认', pattern: rule.pattern, replacement: rule.replacement, scope: rule.scope, is_enabled: rule.is_enabled, order_index: rule.order_index } : {}); selected.value = rule?.id; baseline.value = JSON.stringify(draft) }
async function submit() { if (await save(selected.value, draft)) { selected.value = savedId.value; baseline.value = JSON.stringify(draft) } }
async function confirmDelete() { const id = selected.value; if (!id) return; try { await ElMessageBox.confirm('删除这个替换规则？未保存的修改也会丢弃。', '删除替换规则', { confirmButtonText: '确认删除规则', cancelButtonText: '取消', type: 'warning' }) } catch { return }; if (await remove(id)) { selected.value = undefined; Object.assign(draft, emptyRule()); baseline.value = JSON.stringify(draft) } }
const columns = [{ key: 'action', title: '操作', width: 90, cellRenderer: ({ rowData }: { rowData: Model<'ReplaceRule'> }) => h(ElButton, { disabled: busy.value, onClick: () => edit(rowData) }, () => '编辑') }, { key: 'name', dataKey: 'name', title: '规则名称', width: 230 }, { key: 'order_index', dataKey: 'order_index', title: '顺序', width: 90 }, { key: 'group_name', dataKey: 'group_name', title: '分组', width: 150 }, { key: 'is_enabled', title: '状态', width: 90, cellRenderer: ({ rowData }: { rowData: Model<'ReplaceRule'> }) => h('span', rowData.is_enabled ? '启用' : '停用') }]
onMounted(load); onBeforeRouteLeave(async () => !getSession() ? true : busy.value ? false : await abandon())
</script>
<template>
  <main class="page-width"><RouterLink to="/settings" class="muted">← 阅读设置</RouterLink><div class="page-heading"><div><span class="eyebrow">留下值得阅读的文字</span><h1>替换净化规则<span class="heading-dot">.</span></h1><p class="muted">按顺序从小到大应用正则替换。表达式由服务端校验，使用 RE2 语法；不支持回溯引用和环视。</p></div></div>
    <ElAlert v-if="error" :title="error" type="error" :closable="false" /><ElAlert v-if="notice" :title="notice" type="success" :closable="false" />
    <section class="surface"><div class="section-heading"><h2>规则列表（{{ items.length }}）</h2><div><ElButton :disabled="busy" @click="edit()">新建规则</ElButton><ElButton :disabled="busy" @click="load">刷新规则</ElButton></div></div><div :style="{ height: `${Math.min(Math.max(items.length, 1), 6) * 50 + 50}px` }"><ElAutoResizer><template #default="{height,width}"><ElTableV2 :columns="columns" :data="items" :height="height" :width="width" row-key="id" /></template></ElAutoResizer></div></section>
    <section class="surface"><h2>{{ selected ? '编辑替换规则' : '新建替换规则' }}</h2><p class="muted">保存后需重新打开章节。仅标题规则当前不影响阅读正文；其他已打开页面和设备的离线副本需联网重新获取。并发编辑以最后保存为准。</p><ElForm label-position="top" :disabled="busy" @submit.prevent="submit"><ElFormItem label="规则名称"><ElInput v-model="draft.name" aria-label="规则名称" maxlength="128" /></ElFormItem><ElFormItem label="规则分组"><ElInput v-model="draft.group_name" aria-label="规则分组" maxlength="64" /></ElFormItem><ElFormItem label="表达式"><ElInput v-model="draft.pattern" aria-label="替换表达式" type="textarea" :rows="3" maxlength="4096" /></ElFormItem><ElFormItem label="替换文本（留空表示删除匹配内容）"><ElInput v-model="draft.replacement" aria-label="替换文本" type="textarea" :rows="2" maxlength="4096" /></ElFormItem><ElFormItem label="作用范围"><ElSelect v-model="draft.scope" aria-label="规则作用范围"><ElOption label="正文" value="content" /><ElOption label="标题（不应用于正文）" value="title" /><ElOption label="全部" value="all" /></ElSelect></ElFormItem><ElFormItem label="执行顺序"><ElInputNumber :model-value="draft.order_index" aria-label="规则执行顺序" :min="-2147483648" :max="2147483647" :precision="0" @update:model-value="value => value != null && (draft.order_index = value)" /></ElFormItem><ElFormItem label="启用规则"><ElSwitch v-model="draft.is_enabled" aria-label="启用规则" /></ElFormItem><div class="button-row"><ElButton type="primary" native-type="submit" :loading="busy">保存替换规则</ElButton><ElButton v-if="selected" type="danger" :disabled="busy" @click="confirmDelete">删除替换规则</ElButton><span v-if="dirty" class="muted">有未保存修改</span></div></ElForm></section>
  </main>
</template>
<style scoped>h2 { font-size: 18px; font-weight: 500; }.el-select { width: min(320px,100%); }.section-heading { flex-wrap: wrap; }</style>
